            current_size = current_mask.bit_count()

            for x in range(26):
                bit = 1 << x

                if current_size == k and (current_mask & bit) == 0:
                    q = get_overflow(i + 1, bit)
                    total = completed_so_far + 2 + suffix[q]
                else:
                    q = get_overflow(i + 1, current_mask | bit)
                    total = completed_so_far + 1 + suffix[q]

                if total > answer:
                    answer = total

        return answer
