from typing import List

class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        n = len(nums)
        sorted_nums = nums[:]

        i = 0
        while i < n:
            j = i
            bits = bin(nums[i]).count("1")

            while j < n and bin(nums[j]).count("1") == bits:
                j += 1

            sorted_nums[i:j] = sorted(nums[i:j])
            i = j

        return all(sorted_nums[i] <= sorted_nums[i + 1] for i in range(n - 1))
